package at.heinz.deviceai.learning

import java.io.File
import java.io.FileOutputStream
import java.nio.file.Files
import java.nio.file.StandardCopyOption
import java.nio.file.AtomicMoveNotSupportedException

/** Bounded metadata-only audit of outcomes, NOT text generated by local LLMs.
 * The dialogue does not become a user-confirmed fact through this journal.
 */
class ContinuumRuntimeEventJournal(private val appDirectory:File) {
    private val folder=File(appDirectory,"learning-core-v2")
    private val file=File(folder,"runtime-events-v1.tsv")

    data class Summary(val successes:Int,val failures:Int,val recent:List<String>)

    @Synchronized fun recordLocalOutcome(success:Boolean,at:Long=System.currentTimeMillis()) {
        require(at>=0)
        val event=at.toString()+"\t"+if(success)"LOCAL_MODEL_OK" else "LOCAL_MODEL_FAILED"
        val old=read().recent
        val entries=(old+event).takeLast(16)
        require(entries.joinToString("\n").length<1500)
        if(!folder.exists())check(folder.mkdirs())
        val pending=File.createTempFile("runtime-events-",".tmp",folder)
        try {
            FileOutputStream(pending).use {
                it.write(entries.joinToString("\n",postfix="\n").toByteArray(Charsets.UTF_8))
                it.fd.sync()
            }
            try {
                Files.move(pending.toPath(),file.toPath(),StandardCopyOption.ATOMIC_MOVE,
                    StandardCopyOption.REPLACE_EXISTING)
            } catch(_:AtomicMoveNotSupportedException) {
                Files.move(pending.toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING)
            }
        } finally { pending.delete() }
    }

    @Synchronized fun read():Summary {
        if(!file.exists())return Summary(0,0,emptyList())
        require(file.length() in 0..1500) { "Invalid runtime event ledger size" }
        val records=file.readLines(Charsets.UTF_8).filter(String::isNotBlank)
        require(records.size<=16)
        for(record in records) {
            val parts=record.split('\t')
            require(parts.size==2 && parts[0].toLongOrNull()!=null &&
                parts[1] in setOf("LOCAL_MODEL_OK","LOCAL_MODEL_FAILED")) {
                "Invalid runtime event ledger row"
            }
        }
        return Summary(records.count { it.endsWith("LOCAL_MODEL_OK") },
            records.count { it.endsWith("LOCAL_MODEL_FAILED") },records)
    }
}
